   332	ReadCharData(mat_t *mat,char *data,enum matio_types data_type,int len)
   333	{
   334	    int bytesread = 0;
   335	    size_t data_size;
   336	
   337	    if ( mat == NULL || data == NULL || mat->fp == NULL )
   338	        return 0;
   339	
   340	    data_size = Mat_SizeOf(data_type);
   341	
   342	    switch ( data_type ) {
   343	        case MAT_T_UINT8:
   344	        case MAT_T_UTF8:
   345	            bytesread += fread(data,data_size,len,(FILE*)mat->fp);
   346	            break;
   347	        case MAT_T_UINT16:
   348	        case MAT_T_UTF16:
   349	        {
   350	            mat_uint16_t ui16;
   351	            int i;
   352	            if ( mat->byteswap ) {
   353	                for ( i = 0; i < len; i++ ) {
   354	                    bytesread += fread(&ui16,data_size,1,(FILE*)mat->fp);
   355	                    data[i] = (char)Mat_uint16Swap(&ui16);
   356	                }
   357	            } else {
   358	                for ( i = 0; i < len; i++ ) {
   359	                    bytesread += fread(&ui16,data_size,1,(FILE*)mat->fp);
   360	                    data[i] = (char)ui16;
   361	                }
   362	            }
   363	            break;
   364	        }
   365	        default:
   366	            Mat_Warning("ReadCharData: %d is not a supported data type for "
   367	                "character data", data_type);
   368	            break;
   369	    }
   370	    return bytesread;
   371	}
